import numpy as npimport pandas as pdimport matplotlib.pyplot as pltfrom sklearn.model_selection import train_test_splitfrom sklearn.preprocessing import StandardScalerfrom sklearn.preprocessing import LabelEncoderfrom sklearn.svm import SVCfrom matplotlib.colors import ListedColormapfrom sklearn.metrics import accuracy_scorefrom sklearn.model_selection import GridSearchCVfrom tqdm import tqdmfrom math import factorialimport randomfrom itertools import combinations### I need to do a grid search firstparam_grid = {'C': [0.1, 1, 10, 100, 1000, 10000], 			'gamma': [1, 0.1, 0.01, 0.001, 0.0001, 0.00001], 			'kernel': ['rbf']} model_performance = pd.DataFrame()for clusterx in tqdm(range(0,26)):    if clusterx in [14,18,21] :        continue        base_path = "/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/degs_0.1_f_m/cluster_"    path = f"{base_path}{clusterx}.csv"    cluster_data = pd.read_csv(path)        # set up training data    training_data = cluster_data[cluster_data['Status'].isin(['M','F'])]    training_labels = np.where(training_data['Status']=='M', 0, 1)    training_matrix = training_data.iloc[:,3:].to_numpy()        svm_base = SVC()        grid_search = GridSearchCV(            estimator=svm_base,            param_grid=param_grid,            cv=5,            scoring='accuracy')            grid_search.fit(training_matrix, training_labels)            best_model = grid_search.best_estimator_    best_c = grid_search.best_params_['C']    best_gamma = grid_search.best_params_['gamma']    best_score = grid_search.best_score_                   data_to_bind = pd.DataFrame({           'cluster': [clusterx],           'best_C': [best_c],           'best_gamma':[best_gamma],           'cv_score': [best_score]           })    model_performance = pd.concat([model_performance, data_to_bind], ignore_index=True)model_performance['best_C'].value_counts() ##10 is overwhelmingly the bestmodel_performance['best_gamma'].value_counts() ### definitely 1### analysis timesvm_data = pd.DataFrame()conv_df = pd.DataFrame()exh_df = pd.DataFrame()sin_df = pd.DataFrame()for clusterx in (range(0,26)):    if clusterx in [21] :        continue        base_path = "/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/degs_0.1_f_m//cluster_"    path = f"{base_path}{clusterx}.csv"    cluster_data = pd.read_csv(path)        n_degs = cluster_data.shape[1] - 3            if n_degs > 8:        #test  all combinations of size 7        #so what I want to do is sample (with replacement?) n of 7 with a range of        #n_degs                for samp in tqdm(range(5040)):            svm = SVC(C=10, gamma=1, kernel='rbf')            random_deg_cols = random.sample(range(1, n_degs), 7) #7 random cols            random_deg_colsx = [x+3 for x in random_deg_cols] # update to reflect correct col ids                        selected_cols = [cluster_data.columns[i] for i in random_deg_colsx]                        # set up training data            training_data = cluster_data[cluster_data['Status'].isin(['M','F'])]            training_labels = np.where(training_data['Status']=='M', 0, 1)            training_matrix = training_data[selected_cols].to_numpy()                    #set up test data            test_data = cluster_data[cluster_data['Status'].isin(['D'])]            test_matrix = test_data[selected_cols].to_numpy()                        # scale data            scaler = StandardScaler()            scaler.fit(training_matrix)            train_std_x = scaler.transform(training_matrix)            test_std_x = scaler.transform(test_matrix)                        svm.fit(train_std_x, training_labels)            predictions = svm.predict(test_std_x)                        mean_pred = predictions.mean()                        new_df = pd.DataFrame({                'cluster': [clusterx],                'iter': [samp],                'pred' : [mean_pred]})                        conv_df = pd.concat([conv_df, new_df])                        elif n_degs > 2:            #test all combinations of size n-1                        deg_columns = cluster_data.iloc[:,3:].columns            it = 1            for combo in tqdm(combinations(deg_columns, n_degs-1)):                svm = SVC(C=10, gamma=1, kernel='rbf')                selected_cols = list(combo)                                   # set up training data                training_data = cluster_data[cluster_data['Status'].isin(['M','F'])]                training_labels = np.where(training_data['Status']=='M', 0, 1)                training_matrix = training_data[selected_cols].to_numpy()                            #set up test data                test_data = cluster_data[cluster_data['Status'].isin(['D'])]                test_matrix = test_data[selected_cols].to_numpy()                                # scale data                scaler = StandardScaler()                scaler.fit(training_matrix)                train_std_x = scaler.transform(training_matrix)                test_std_x = scaler.transform(test_matrix)                                svm.fit(train_std_x, training_labels)                predictions = svm.predict(test_std_x)                                mean_pred = predictions.mean()                                new_df = pd.DataFrame({                    'cluster': [clusterx],                    'iter': [it],                    'pred' : [mean_pred]})                                exh_df = pd.concat([exh_df,new_df ])                                it = it + 1                                else:        #no neeed for combinatorial testing        svm = SVC(C=10, gamma=1, kernel='rbf')        # set up training data        training_data = cluster_data[cluster_data['Status'].isin(['M','F'])]        training_labels = np.where(training_data['Status']=='M', 0, 1)        training_matrix = training_data.iloc[:,3:].to_numpy()                # set up test data        test_data = cluster_data[cluster_data['Status'].isin(['D'])]        test_matrix = test_data.iloc[:,3:].to_numpy()                # scale data        scaler = StandardScaler()        scaler.fit(training_matrix)        train_std_x = scaler.transform(training_matrix)        test_std_x = scaler.transform(test_matrix)                svm.fit(train_std_x, training_labels)        predictions = svm.predict(test_std_x)                mean_pred = predictions.mean()                new_df = pd.DataFrame({            'cluster': [clusterx],            'pred' : [mean_pred]})                sin_df = pd.concat([sin_df, new_df ])# calculate cumsums for conv_dfconv_df['cummean'] = Nonefor cluster in set(conv_df['cluster']):    conv_df['cummean'][conv_df['cluster']==cluster] = np.cumsum(conv_df['pred'][conv_df['cluster']==cluster])/ ((conv_df['iter'][conv_df['cluster']==cluster])+1)  set(conv_df['cluster'])plt.plot(conv_df['iter'][conv_df['cluster']==6],conv_df['cummean'][conv_df['cluster']==6])  plt.plot(conv_df['iter'][conv_df['cluster']==1],conv_df['cummean'][conv_df['cluster']==1])  plt.plot(conv_df['iter'][conv_df['cluster']==11],conv_df['cummean'][conv_df['cluster']==11])  plt.plot(conv_df['iter'][conv_df['cluster']==0],conv_df['cummean'][conv_df['cluster']==0])  plt.plot(conv_df['iter'][conv_df['cluster']==2],conv_df['cummean'][conv_df['cluster']==2])  ## exh_dfexh_df['cummean'] = Nonefor cluster in set(exh_df['cluster']):    exh_df['cummean'][exh_df['cluster']==cluster] = np.cumsum(exh_df['pred'][exh_df['cluster']==cluster])/ ((exh_df['iter'][exh_df['cluster']==cluster])+1)set(exh_df['cluster'])set(sin_df['cluster'])#### chat gpt is writing this cause im too tired to do it rn, i asked it to find the final converged prediction and put it into a dffinal_results = pd.DataFrame()# Function to extract final mean predictiondef extract_final_means(df, iter_col='iter'):    final_means = []    for cluster in sorted(df['cluster'].unique()):        cluster_df = df[df['cluster'] == cluster]        max_iter = cluster_df[iter_col].max()        final_mean = cluster_df.loc[cluster_df[iter_col] == max_iter, 'cummean'].values[0]        final_means.append({'cluster': cluster, 'final_cummean': final_mean})    return pd.DataFrame(final_means)# Extract final cummean for conv_df and exh_dfconv_final = extract_final_means(conv_df)conv_final['type'] = 'conv'exh_final = extract_final_means(exh_df)exh_final['type'] = 'exh'# Compute mean pred for sin_df directlysin_means = sin_df.groupby('cluster')['pred'].mean().reset_index()sin_means = sin_means.rename(columns={'pred': 'final_cummean'})sin_means['type'] = 'sin'# Get n_degs for each cluster from source data againn_degs_map = {}for clusterx in range(26):    if clusterx == 21:        continue    path = f"/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/degs_0.1_f_m//cluster_{clusterx}.csv"    cluster_data = pd.read_csv(path)    n_degs = cluster_data.shape[1] - 3    n_degs_map[clusterx] = n_degs# Combine all into a single dataframefinal_results = pd.concat([conv_final, exh_final, sin_means], ignore_index=True)final_results['n_degs'] = final_results['cluster'].map(n_degs_map)# Show resultsprint(final_results)#final_results.to_csv("/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/converged_svm_predictions_06_17_2025.csv") 